// Turns the sheet rows into the Actor input.
// Required columns: name, email. Any other column (course, date, hours...) can be used in the text as {{column}}.
const rows = $input.all().map(i => i.json).filter(r => r.name && r.email);
const year = new Date().getFullYear();
const records = rows.map((r, i) => ({
  ...r,
  certificateId: r.certificateId || `CERT-${year}-${String(i + 1).padStart(4, '0')}`,
}));

return [{
  json: {
    records,
    actorInput: {
      records,
      template: 'certificate-classic',           // or certificate-modern, diploma-kids
      title: 'Certificate',
      subtitle: 'of completion',
      body: 'Awarded for successfully completing {{course}}.',
      date: '{{date}}',
      issuer: 'Your School Name',
      signature1Name: 'Jane Doe',
      signature1Title: 'Director',
      accentColor: '#1f4e8c',
      outputZip: true,
    },
  },
}];

// Adds each person's email back to the generated certificate.
const records = $('Build Actor input').first().json.records;
const byId = Object.fromEntries(records.map(r => [r.certificateId, r]));
return $input.all()
  .map(item => {
    const person = byId[item.json.certificateId] || {};
    return { json: { ...item.json, email: person.email, course: person.course || '' } };
  })
  .filter(item => item.json.email && item.json.pdfUrl);
